import{_ as e,o as s,c as t,a2 as r}from"./chunks/framework.Cs11k9ph.js";const q=JSON.parse('{"title":"❓ 常见问题（v2.8）","description":"","frontmatter":{},"headers":[],"relativePath":"faq.md","filePath":"faq.md","lastUpdated":1788070985000}'),o={name:"faq.md"};function i(n,a,l,h,d,p){return s(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="❓-常见问题-v2-8" tabindex="-1">❓ 常见问题（v2.8） <a class="header-anchor" href="#❓-常见问题-v2-8" aria-label="Permalink to &quot;❓ 常见问题（v2.8）&quot;">​</a></h1><blockquote><p>本文档对应 <strong>AgoraIn v2.8</strong>（AgoraInPro）。旧版 v2.7 文档已归档：<a href="/v2.7/faq.html">v2.7 常见问题</a>。</p></blockquote><h2 id="构建与运行" tabindex="-1">构建与运行 <a class="header-anchor" href="#构建与运行" aria-label="Permalink to &quot;构建与运行&quot;">​</a></h2><h3 id="q-构建报-文件被占用-无法复制-agorain-exe" tabindex="-1">Q: 构建报&quot;文件被占用 / 无法复制 AgoraIn.exe&quot;？ <a class="header-anchor" href="#q-构建报-文件被占用-无法复制-agorain-exe" aria-label="Permalink to &quot;Q: 构建报&quot;文件被占用 / 无法复制 AgoraIn.exe&quot;？&quot;">​</a></h3><p><strong>A:</strong> 先结束旧进程再构建：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Stop-Process</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Name AgoraIn </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Force</span></span></code></pre></div><h3 id="q-自测命令怎么用" tabindex="-1">Q: 自测命令怎么用？ <a class="header-anchor" href="#q-自测命令怎么用" aria-label="Permalink to &quot;Q: 自测命令怎么用？&quot;">​</a></h3><p><strong>A:</strong> 在客户端目录执行：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> .\\AgoraInPro\\bin\\Debug\\net10.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">windows\\</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">AgoraIn.exe</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">selftest</span></span></code></pre></div><p>退出码 0 表示全部通过。</p><hr><h2 id="服务器与连接" tabindex="-1">服务器与连接 <a class="header-anchor" href="#服务器与连接" aria-label="Permalink to &quot;服务器与连接&quot;">​</a></h2><h3 id="q-服务器提示-未配置-serverpassword-已自动生成" tabindex="-1">Q: 服务器提示&quot;未配置 ServerPassword，已自动生成&quot;？ <a class="header-anchor" href="#q-服务器提示-未配置-serverpassword-已自动生成" aria-label="Permalink to &quot;Q: 服务器提示&quot;未配置 ServerPassword，已自动生成&quot;？&quot;">​</a></h3><p><strong>A:</strong> 这是安全默认行为。请打开服务器目录 <code>config.json</code> 查看生成的密码，并在客户端「远程服务器设置」中填入。</p><h3 id="q-客户端连不上服务器" tabindex="-1">Q: 客户端连不上服务器？ <a class="header-anchor" href="#q-客户端连不上服务器" aria-label="Permalink to &quot;Q: 客户端连不上服务器？&quot;">​</a></h3><p><strong>A:</strong> 依次检查：</p><ol><li>服务器端口（默认 5250）是否开放</li><li>服务器 IP 是否正确</li><li>服务器 <code>config.json</code> 中的 <code>ServerPassword</code> 是否与客户端一致</li><li>客户端与服务器是否在同一局域网</li></ol><h3 id="q-服务器地址填哪里" tabindex="-1">Q: 服务器地址填哪里？ <a class="header-anchor" href="#q-服务器地址填哪里" aria-label="Permalink to &quot;Q: 服务器地址填哪里？&quot;">​</a></h3><p><strong>A:</strong> 客户端菜单 <strong>远程 → 远程服务器设置</strong>，填写服务器 IP、端口（默认 5250）与密码。</p><hr><h2 id="排课与课时" tabindex="-1">排课与课时 <a class="header-anchor" href="#排课与课时" aria-label="Permalink to &quot;排课与课时&quot;">​</a></h2><h3 id="q-排课无法提交" tabindex="-1">Q: 排课无法提交？ <a class="header-anchor" href="#q-排课无法提交" aria-label="Permalink to &quot;Q: 排课无法提交？&quot;">​</a></h3><p><strong>A:</strong> 检查：</p><ul><li>上课/下课时间是否已填写（格式 HH:mm）</li><li>下课时间不得等于上课时间</li><li>重复排课会被拦截</li></ul><h3 id="q-开启自动扣减后课时未变化" tabindex="-1">Q: 开启自动扣减后课时未变化？ <a class="header-anchor" href="#q-开启自动扣减后课时未变化" aria-label="Permalink to &quot;Q: 开启自动扣减后课时未变化？&quot;">​</a></h3><p><strong>A:</strong> 确认：</p><ul><li>排课的起止时间均有效</li><li>课程已到下课时间</li><li>系统每 30 秒检查一次，同一时段不会重复扣减（SlotKey 去重）</li></ul><h3 id="q-如何设置每小时课时消耗" tabindex="-1">Q: 如何设置每小时课时消耗？ <a class="header-anchor" href="#q-如何设置每小时课时消耗" aria-label="Permalink to &quot;Q: 如何设置每小时课时消耗？&quot;">​</a></h3><p><strong>A:</strong> 在「控制模式 → 划课」的设置项中配置 <strong>每小时课时消耗</strong>，支持小数（如 0.5 / 1 / 1.5，范围 0–24）。</p><h3 id="q-排课支持跨天课程吗" tabindex="-1">Q: 排课支持跨天课程吗？ <a class="header-anchor" href="#q-排课支持跨天课程吗" aria-label="Permalink to &quot;Q: 排课支持跨天课程吗？&quot;">​</a></h3><p><strong>A:</strong> 支持。如 <code>23:00–01:00</code> 的跨天课程，下课时间不得等于上课时间即可。</p><h3 id="q-怎么设置不排课日" tabindex="-1">Q: 怎么设置不排课日？ <a class="header-anchor" href="#q-怎么设置不排课日" aria-label="Permalink to &quot;Q: 怎么设置不排课日？&quot;">​</a></h3><p><strong>A:</strong> 在月历中选中日期，点击 <strong>设为不排课日</strong>，系统自动清空当日排课并以粉底&quot;休&quot;标记；周末默认提示为不排课。</p><hr><h2 id="数据与安全" tabindex="-1">数据与安全 <a class="header-anchor" href="#数据与安全" aria-label="Permalink to &quot;数据与安全&quot;">​</a></h2><h3 id="q-课时数据存储在哪里" tabindex="-1">Q: 课时数据存储在哪里？ <a class="header-anchor" href="#q-课时数据存储在哪里" aria-label="Permalink to &quot;Q: 课时数据存储在哪里？&quot;">​</a></h3><p><strong>A:</strong> 客户端目录下的 <code>data/classhours.json</code>（版本 v3），包含学生课时、流水、排课、不排课日与自动划消设置。</p><h3 id="q-服务器数据存储在哪里" tabindex="-1">Q: 服务器数据存储在哪里？ <a class="header-anchor" href="#q-服务器数据存储在哪里" aria-label="Permalink to &quot;Q: 服务器数据存储在哪里？&quot;">​</a></h3><p><strong>A:</strong> 服务器目录的 SQLite 数据库中，包含设备、任务、考勤、用户、签到任务等。</p><h3 id="q-密码安全吗" tabindex="-1">Q: 密码安全吗？ <a class="header-anchor" href="#q-密码安全吗" aria-label="Permalink to &quot;Q: 密码安全吗？&quot;">​</a></h3><p><strong>A:</strong> 安全。用户密码采用<strong>加盐 SHA256</strong> 哈希存储；管理员密码通过 SHA256 哈希校验；服务器密码未配置时自动生成随机密码。</p><h3 id="q-如何备份数据" tabindex="-1">Q: 如何备份数据？ <a class="header-anchor" href="#q-如何备份数据" aria-label="Permalink to &quot;Q: 如何备份数据？&quot;">​</a></h3><p><strong>A:</strong> 直接复制数据文件即可：客户端课时数据（<code>data/classhours.json</code>）、服务器 SQLite 数据库。恢复时覆盖原文件（建议先停止程序）。</p><hr><h2 id="其他" tabindex="-1">其他 <a class="header-anchor" href="#其他" aria-label="Permalink to &quot;其他&quot;">​</a></h2><h3 id="q-旧版-v2-7-文档在哪里" tabindex="-1">Q: 旧版 v2.7 文档在哪里？ <a class="header-anchor" href="#q-旧版-v2-7-文档在哪里" aria-label="Permalink to &quot;Q: 旧版 v2.7 文档在哪里？&quot;">​</a></h3><p><strong>A:</strong> 已归档，可通过 <a href="/v2.7/">旧版文档主页</a> 或站点导航中的&quot;旧版文档（v2.7）&quot;入口查看。</p>',47)])])}const g=e(o,[["render",i]]);export{q as __pageData,g as default};
